targets.expr:
(
  count(current_consumption:total > $power_alert_threshold) or vector(0)
) + (
  count(consumption_cost:total > $cost_alert_threshold) or vector(0)
) + (
  count(consumption_cost:anomaly == 1) or vector(0)
) + (
  count(rate_class:numeric == 3) or vector(0)
) + (
  count(state{version=~"$version"} != 1) or vector(0)
)

(
  count(current_consumption:total{version=~"$version"} > ($power_alert_threshold * 0.8)) or vector(0)
) + (
  count(consumption_cost:total{version=~"$version"} > ($cost_alert_threshold * 0.8)) or vector(0)
) + (
  count(rssi{version=~"$version"} < -70) or vector(0)
)

clamp_max(
  (
    count(current_consumption:total{version=~"$version"} > $power_alert_threshold) or vector(0)
  ) + (
    count(consumption_cost:total{version=~"$version"} > $cost_alert_threshold) or vector(0)
  ) + (
    count(consumption_cost:anomaly{version=~"$version"} == 1) or vector(0)
  ),
  1
)
